import numpy as np
from PIL import Image
from collections import deque
a=np.array(Image.open('mol_0257.png').convert('L'))
mask=a<128
H,W=mask.shape
lab=-np.ones((H,W),int)
comps=[]
for y in range(H):
    for x in range(W):
        if mask[y,x] and lab[y,x]<0:
            q=deque([(y,x)]); lab[y,x]=len(comps); pix=[]
            while q:
                cy,cx=q.popleft(); pix.append((cy,cx))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and lab[ny,nx]<0:
                            lab[ny,nx]=len(comps); q.append((ny,nx))
            comps.append(pix)
print(len(comps))
import pickle
info=[]
for i,p in enumerate(comps):
    arr=np.array(p)
    ys,xs=arr[:,0],arr[:,1]
    info.append((i,len(p),xs.min(),xs.max(),ys.min(),ys.max()))
for t in info:
    if t[1]>20: print(t)
pickle.dump((lab,comps),open('cc.pkl','wb'))
EOF
